// src/modules/dashboard/Dashboard.js
import React from "react";
import Sidebar from "../../components/Sidebar";
import Header from "../../components/Header";
import TopCandidates from "../../components/TopCandidates";
import "./Dashboard.css";
import "../../index.css"; // <-- correct global CSS import (important)
import { FaUsers, FaDollarSign, FaChartLine, FaUserCheck } from "react-icons/fa";

function Dashboard() {
  // Try to infer some live counts from localStorage (non-destructive)
  const freelancerProfiles = JSON.parse(localStorage.getItem("freelancerProfiles") || "[]");
  const jobSeekerProfiles = JSON.parse(localStorage.getItem("jobSeekerProfiles") || "[]");
  const companyProfiles = JSON.parse(localStorage.getItem("companyProfiles") || "[]");

  // Example metrics: combine totals for active candidates
  const activeCandidates = freelancerProfiles.length + jobSeekerProfiles.length || 2847; // fallback to original number
  const avgMatchScore = (() => {
    // If you have stored match scores, you could compute an average.
    // For now, keep fallback 87
    return 87;
  })();

  const revenueThisMonth = (() => {
    // If you plan to keep revenue in localStorage, read it here; otherwise fallback.
    const rev = localStorage.getItem("revenueThisMonth");
    return rev ? Number(rev) : 124500;
  })();

  const activeDeals = (() => {
    const d = localStorage.getItem("activeDeals");
    return d ? Number(d) : 47;
  })();

  // get current user for greeting
  let currentUser = null;
  try {
    const cu = JSON.parse(localStorage.getItem("currentUser") || "null");
    currentUser = cu && cu.email ? cu.email : null;
  } catch (e) {
    currentUser = null;
  }

  return (
    <div className="dashboard-container">
      <Sidebar />
      <div className="dashboard-main">
        <Header />

        <div className="dashboard-content">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
            <div>
              <h1 className="dashboard-title">Dashboard</h1>
              {currentUser && <p style={{ margin: 0, color: "#556070" }}>Welcome back, <strong>{currentUser}</strong></p>}
            </div>
          </div>

          <div className="cards-container">
            <div className="card">
              <div className="card-icon"><FaUsers /></div>
              <div className="card-info">
                <p className="card-title">Active Candidates</p>
                <p className="card-value">{activeCandidates.toLocaleString()} <span className="up-arrow">▲ 12.5%</span></p>
              </div>
            </div>
             
            <div className="card">
              <div className="card-icon"><FaUserCheck /></div>
              <div className="card-info">
                <p className="card-title">Avg Match Score</p>
                <p className="card-value">{avgMatchScore}% <span className="up-arrow">▲ 5.2%</span></p>
              </div>
            </div>

            <div className="card">
              <div className="card-icon"><FaDollarSign /></div>
              <div className="card-info">
                <p className="card-title">Revenue This Month</p>
                <p className="card-value">${Number(revenueThisMonth).toLocaleString()} <span className="up-arrow">▲ 8.1%</span></p>
              </div>
            </div>

            <div className="card">
              <div className="card-icon"><FaChartLine /></div>
              <div className="card-info">
                <p className="card-title">Active Deals</p>
                <p className="card-value">{activeDeals} <span className="down-arrow">▼ 2.4%</span></p>
              </div>
            </div>
          </div>

          {/* Top Candidates Section */}
          <div style={{ marginTop: 28 }}>
            <TopCandidates />
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
